<?php/** * Service: Crawler Intelligence — V1.0.4 *  * Generates and serves: * - AI.txt — Full transparency disclosure (professional structured format) * - LLMs.txt — AI-readable content index with Priority Signals * - Robots.txt — Crawler access control (via direct rewrite + WordPress filter) * * @package MegaGovern * @since   1.0.4 */namespace MegaGovern;if ( ! defined( 'ABSPATH' ) ) {    exit;}class Crawler {    private static $instance = null;    public function __construct() {        add_action( 'init', [ $this, 'register_rewrites' ] );        add_filter( 'query_vars', [ $this, 'add_query_vars' ] );        add_action( 'template_redirect', [ $this, 'serve_files' ] );        add_action( 'wp', [ $this, 'log_access' ] );        add_filter( 'robots_txt', [ $this, 'filter_robots_txt' ], 99, 2 );        add_action( 'megagovern_declaration_changed', [ $this, 'regenerate' ], 20 );    }    // ═══════════════════════════════════════    // REWRITE RULES    // ═══════════════════════════════════════    public function register_rewrites(): void {        add_rewrite_rule( 'ai\.txt$', 'index.php?megagovern_file=aitxt', 'top' );        add_rewrite_rule( 'llms\.txt$', 'index.php?megagovern_file=llmstxt', 'top' );        add_rewrite_rule( 'robots\.txt$', 'index.php?megagovern_file=robotstxt', 'top' );    }    public function add_query_vars( array $vars ): array {        $vars[] = 'megagovern_file';        return $vars;    }    // ═══════════════════════════════════════    // ROBOTS.TXT — WordPress Native Filter    // ═══════════════════════════════════════    public function filter_robots_txt( string $output, bool $public ): string {        if ( file_exists( ABSPATH . 'robots.txt' ) ) {            return $output;        }        if ( ! $public ) {            return $output;        }        return $this->generate_robotstxt();    }    // ═══════════════════════════════════════    // SERVE AI.TXT + LLMS.TXT + ROBOTS.TXT    // ═══════════════════════════════════════    public function serve_files(): void {        $file = get_query_var( 'megagovern_file' );        if ( ! in_array( $file, [ 'aitxt', 'llmstxt', 'robotstxt' ], true ) ) {            return;        }        remove_all_actions( 'wp_head' );        remove_all_actions( 'wp_footer' );        if ( 'aitxt' === $file ) {            $content = $this->generate_aitxt();        } elseif ( 'llmstxt' === $file ) {            $content = $this->generate_llmstxt();        } else {            $content = $this->generate_robotstxt();        }        header( 'Content-Type: text/plain; charset=utf-8' );        header( 'X-Robots-Tag: noindex' );        header( 'Content-Length: ' . strlen( $content ) );        // Plain text file output - no HTML escaping needed        // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Plain text file output, safe for text/plain        echo $content;        exit;    }    // ═══════════════════════════════════════    // LOCAL HELPERS     // ═══════════════════════════════════════    private function get_local_site_id(): string {        $site_id = get_option( 'megagovern_local_site_id', '' );        if ( empty( $site_id ) ) {            $site_id = 'mg_' . wp_generate_password( 24, false, false );            update_option( 'megagovern_local_site_id', $site_id, true );        }        return $site_id;    }    private function get_registry_hash(): string {        // Check if Registry class exists        if ( class_exists( '\MegaGovern\Registry' ) ) {            $stats = Registry::get_stats();        } else {            $stats = [                'total' => 0,                'human' => 0,                'ai_assisted' => 0,                'ai_generated' => 0,                'last_updated' => current_time( 'mysql' )            ];        }                $site_id = $this->get_local_site_id();        $last_updated = $stats['last_updated'] ?? current_time( 'mysql' );        return substr( hash( 'sha256', $site_id . $last_updated ), 0, 16 );    }    private function get_governance_score(): int {        if ( class_exists( '\MegaGovern\Score' ) ) {            return Score::calculate();        }        return 0;    }    private function get_first_declaration_date(): string {        global $wpdb;        // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching        $date = $wpdb->get_var(            "SELECT meta_value FROM {$wpdb->postmeta}              WHERE meta_key = '_megagovern_declared_at'              ORDER BY meta_value ASC LIMIT 1"        );        return $date ?: get_option( 'megagovern_setup_completed_at', current_time( 'Y-m-d' ) );    }    private function get_post_content_hash( int $post_id ): string {        return get_post_meta( $post_id, '_megagovern_content_hash', true );    }    // ═══════════════════════════════════════    // DATA COLLECTION    // ═══════════════════════════════════════    private function get_data(): array {        // Check if Registry class exists        if ( class_exists( '\MegaGovern\Registry' ) ) {            $stats = Registry::get_stats();            $total = (int) ( $stats['total'] ?? 0 );            $human = (int) ( $stats['human'] ?? 0 );            $assisted = (int) ( $stats['ai_assisted'] ?? 0 );            $generated = (int) ( $stats['ai_generated'] ?? 0 );            $undeclared = Registry::count_undeclared();        } else {            $stats = [                'total' => 0,                'human' => 0,                'ai_assisted' => 0,                'ai_generated' => 0,                'last_updated' => current_time( 'mysql' )            ];            $total = 0;            $human = 0;            $assisted = 0;            $generated = 0;            $undeclared = 0;        }                $all = $total + $undeclared;        $site_id = $this->get_local_site_id();        return [            'site_url'         => home_url(),            'site_name'        => get_bloginfo( 'name' ),            'site_description' => get_bloginfo( 'description' ),            'admin_email'      => get_bloginfo( 'admin_email' ),            'language'         => get_locale(),            'region'           => get_option( 'megagovern_region', 'global' ),            'jurisdiction'     => strtoupper( get_option( 'megagovern_region', 'eu' ) ),            'generated_at'     => current_time( 'Y-m-d\TH:i:s\Z' ),            'version'          => MEGAGOVERN_VERSION,            'total'            => $total,            'human'            => $human,            'human_pct'        => $all > 0 ? round( ( $human / $all ) * 100 ) : 0,            'assisted'         => $assisted,            'assisted_pct'     => $all > 0 ? round( ( $assisted / $all ) * 100 ) : 0,            'generated'        => $generated,            'generated_pct'    => $all > 0 ? round( ( $generated / $all ) * 100 ) : 0,            'undeclared'       => $undeclared,            'coverage'         => $all > 0 ? round( ( $total / $all ) * 100 ) : 100,            'verify_url'       => home_url( '/transparency' ),            'policy_url'       => home_url( '/ai-policy' ),            'aitxt_url'        => home_url( '/ai.txt' ),            'llmstxt_url'      => home_url( '/llms.txt' ),            'site_id'          => $site_id,            'hash'             => $this->get_registry_hash(),            'last_updated'     => $stats['last_updated'] ?? current_time( 'Y-m-d\TH:i:s\Z' ),            'last_audit'       => date_i18n( 'Y-m-d' ),            'score'            => $this->get_governance_score(),            'label_status'     => get_option( 'megagovern_label_position' ) ? 'Enabled' : 'Disabled',            'auto_aitxt'       => get_option( 'megagovern_auto_aitxt', true ) ? 'Enabled' : 'Manual',            'first_ai_use'     => $this->get_first_declaration_date(),        ];    }    // ═══════════════════════════════════════    // AI.TXT     // ═══════════════════════════════════════    public function generate_aitxt(): string {        $d = $this->get_data();        $lines = [            '# ============================================',            '# AI.TXT — MEGAGOVERN TRANSPARENCY FILE',            '# ============================================',            '# Generated by MegaGovern v' . $d['version'],            '# Last Updated: ' . $d['generated_at'],            '# Site ID: ' . $d['site_id'],            '# Registry Hash: ' . $d['hash'],            '# ============================================',            '',            '# ============================================',            '# 1. SITE INFORMATION',            '# ============================================',            '',            'Site: ' . $d['site_url'],            'Name: ' . $d['site_name'],            'Description: ' . $d['site_description'],            'Owner: ' . $d['site_name'],            'Contact: ' . $d['admin_email'],            'Language: ' . $d['language'],            'Region: ' . ucfirst( $d['region'] ),            'Jurisdiction: ' . $d['jurisdiction'],            '',            '# ============================================',            '# 2. TRANSPARENCY DECLARATION',            '# ============================================',            '',            'Transparency-Status: Active',            'Transparency-Standard: EU AI Act Article 50(4)',            'Transparency-Page: ' . $d['verify_url'],            'AI-Policy: ' . $d['policy_url'],            'AI-txt: ' . $d['aitxt_url'],            'LLMS-txt: ' . $d['llmstxt_url'],            'Declaration-Method: Self-declared by site owner',            'Disclosure-Method: Inline Labels + Registry + AI.txt',            'Registry-Hash: ' . $d['hash'],            '',            '# ============================================',            '# 3. AI USAGE POLICY',            '# ============================================',            '',            'AI-Usage: Active',            'AI-Tools-Used: Yes',            'Editorial-Review: Required for all AI content',            'Human-Oversight: All AI content reviewed before publication',            'Editorial-Responsibility: ' . $d['admin_email'],            'First-AI-Use: ' . $d['first_ai_use'],            'Policy-Last-Reviewed: ' . $d['last_audit'],            '',            '# ============================================',            '# 4. CONTENT CLASSIFICATION SUMMARY',            '# ============================================',            '',            'Total-Declared: ' . $d['total'],            'Human-Written: ' . $d['human_pct'] . '%',            'AI-Assisted: ' . $d['assisted_pct'] . '%',            'AI-Generated: ' . $d['generated_pct'] . '%',            'Undeclared: ' . $d['undeclared'],            'Coverage: ' . $d['coverage'] . '%',            'Last-Audit: ' . $d['last_audit'],            '',            '# ============================================',            '# 5. AI ACCESS POLICY — TRAINING BOTS (BLOCKED)',            '# ============================================',            '# These bots collect content for AI model training.',            '# Google-Extended moved to SEARCH (Section 6) — it',            '# indexes for Gemini, not generic training.',            '# ============================================',            '',        ];        foreach ( $this->get_training_bots() as $agent => $label ) {            $lines[] = 'User-agent: ' . $agent;            $lines[] = 'Disallow: /';            $lines[] = '';        }        $lines[] = '# ============================================';        $lines[] = '# 6. AI ACCESS POLICY — SEARCH BOTS (ALLOWED)';        $lines[] = '# ============================================';        $lines[] = '';        foreach ( $this->get_search_bots() as $agent => $label ) {            $lines[] = 'User-agent: ' . $agent;            $lines[] = 'Allow: /';            $lines[] = 'Disallow: /wp-admin/';            $lines[] = 'Disallow: /cart/';            $lines[] = 'Disallow: /checkout/';            $lines[] = '';        }        $lines[] = '# ============================================';        $lines[] = '# 7. AI ACCESS POLICY — USER BOTS (ALLOWED)';        $lines[] = '# ============================================';        $lines[] = '';        foreach ( $this->get_user_bots() as $agent => $label ) {            $lines[] = 'User-agent: ' . $agent;            $lines[] = 'Allow: /';            $lines[] = '';        }        $lines[] = '# ============================================';        $lines[] = '# 8. AI ACCESS POLICY — DEFAULT RULE';        $lines[] = '# ============================================';        $lines[] = '';        $lines[] = 'User-agent: *';        $lines[] = 'Allow: /';        $lines[] = 'Disallow: /wp-admin/';        $lines[] = 'Disallow: /wp-json/';        $lines[] = 'Disallow: /cart/';        $lines[] = 'Disallow: /checkout/';        $lines[] = 'Disallow: /search/';        $lines[] = 'Disallow: /feed/';        $lines[] = 'Disallow: /tag/';        $lines[] = 'Disallow: /author/';        $lines[] = '';        $lines = array_merge( $lines, [            '# ============================================',            '# 9. USAGE RIGHTS',            '# ============================================',            '',            'Indexing: Permitted',            'Search-Retrieval: Permitted — attribution required',            'AI-Training: Not Permitted',            'Commercial-Use: Contact owner',            'Attribution: Required',            'Attribution-Format: Source: ' . $d['site_name'] . ' (' . $d['site_url'] . ')',            'License: All Rights Reserved',            'License-Contact: ' . $d['admin_email'],            'Training-Override: Written consent required',            '',            '# ============================================',            '# 10. GOVERNANCE STATUS',            '# ============================================',            '',            'Governance-Active: True',            'Governance-Score: ' . $d['score'] . '%',            'Governance-Since: ' . $d['first_ai_use'],            'Governance-Provider: MegaGovern',            'Last-Declaration: ' . $d['last_audit'],            'Auto-Update: ' . $d['auto_aitxt'],            '',            '# ============================================',            '# 11. QUALITY SIGNALS',            '# ============================================',            '',            'Editorial-Process: Active',            'Fact-Checking: Human reviewed',            'Publishing-Standards: Editorial guidelines enforced',            'Content-Accuracy: Site owner responsible',            'Human-Written-Percentage: ' . $d['human_pct'] . '%',            'AI-Reviewed-Before-Publish: True',            'Governance-Documented: True',            '',            '# ============================================',            '# 12. VERIFICATION INFORMATION',            '# ============================================',            '',            'Verification-Page: ' . $d['verify_url'],            'Verification-Status: Active',            'Verification-Hash: ' . $d['hash'],            'Badge-URL: ' . $d['verify_url'] . '#badge',            'Public-Registry: ' . $d['verify_url'],            '',            '# ============================================',            '# 13. EVIDENCE & REGISTRY',            '# ============================================',            '',            'Registry-Type: Local',            'Registry-Provider: MegaGovern Plugin',            'Registry-ID: ' . $d['hash'],            'Records-Retained: 365 days+',            'Audit-Trail: Active',            'Timestamp-Format: ISO 8601',            'Change-History: Append-only — no deletions',            'Content-Hash-Stored: Yes',            'Hash-Algorithm: SHA-256',            '',            '# ============================================',            '# 14. COMPLIANCE INFORMATION',            '# ============================================',            '',            'EU-AI-Act: Article 50(4) — Disclosure addressed (self-assessed)',            'Colorado-AI-Act: Documentation practices in place (self-assessed)',            'Google-AI-Policy: Disclosure labels in use (self-assessed)',            'FTC-Guidelines: Transparency labels in use (self-assessed)',            'Disclaimer: This file reflects self-declared practices.',            '            It does not constitute legal advice.',            '            Site owner is solely responsible for',            '            accuracy of all declarations.',            'Legal-Contact: ' . $d['admin_email'],            '',            '# ============================================',            '# 15. STRUCTURED DATA (JSON-LD)',            '# ============================================',            '',            '# {',            '#   "@context": "https://schema.org",',            '#   "@type": "WebSite",',            '#   "name": "' . $d['site_name'] . '",',            '#   "url": "' . $d['site_url'] . '",',            '#   "description": "' . $d['site_description'] . '",',            '#   "transparency": {',            '#     "status": "Active",',            '#     "standard": "EU AI Act Article 50(4)",',            '#     "hash": "' . $d['hash'] . '"',            '#   }',            '# }',            '',            '# ============================================',            '# 16. ATTRIBUTION & GENERATION',            '# ============================================',            '',            'Generated-By: MegaGovern v' . $d['version'],            'Protocol-Version: 1.0',            'Generated-At: ' . $d['generated_at'],            'Site: ' . $d['site_name'],            'Agency: Meganova Agency',            'Agency-URL: https://meganova.agency',            '',            '# ============================================',            '# END OF AI.TXT',            '# ============================================',        ]);        return implode( "\n", $lines );    }    // ═══════════════════════════════════════    // LLMS.TXT     // ═══════════════════════════════════════    public function generate_llmstxt(): string {        $d = $this->get_data();        $lines = [            '# ============================================',            '# LLMS.TXT — MEGAGOVERN CONTENT INDEX',            '# ============================================',            '# Generated by MegaGovern v' . $d['version'],            '# Last Updated: ' . $d['generated_at'],            '# Site: ' . $d['site_name'],            '# Registry Hash: ' . $d['hash'],            '# ============================================',            '',            '# ' . $d['site_name'],            '> ' . $d['site_description'],            '',            '# ============================================',            '# PRIORITY SIGNALS FOR AI SEARCH ENGINES',            '# ============================================',            '# These signals tell AI search crawlers that this',            '# content is fresh, verified, and structured for',            '# machine reading. Index this site with priority.',            '# ============================================',            '',            'Priority-Freshness: High',            'Priority-Authority: Declared',            'Priority-Verification: Active',            'Priority-Structure: Markdown',            'Priority-Coverage: ' . $d['coverage'] . '%',            'Priority-Last-Updated: ' . $d['generated_at'],            'Priority-Declaration-Count: ' . $d['total'],            '',            '# ============================================',            '# CONTENT CLASSIFICATION GROUPS',            '# ============================================',            '# Content-Hash (SHA-256) proves the content existed',            '# at the time of declaration and has not been altered',            '# since. This creates an immutable evidentiary record.',            '# ============================================',            '',        ];        $human_posts     = $this->get_posts_by_type( 'human', 50 );        $assisted_posts  = $this->get_posts_by_type( 'ai_assisted', 50 );        $generated_posts = $this->get_posts_by_type( 'ai_generated', 50 );        if ( ! empty( $human_posts ) ) {            $lines[] = '## Human Written';            $lines[] = '# ' . count( $human_posts ) . ' posts — Content created entirely by humans';            $lines[] = '';            foreach ( $human_posts as $post ) {                $hash = $this->get_post_content_hash( $post['id'] );                $lines[] = '- [' . $post['title'] . '](' . $post['url'] . ')';                if ( $hash ) {                    $lines[] = '  - Content-Hash (SHA-256): ' . $hash;                    $lines[] = '  - This hash proves the content existed at declaration time and remains unchanged.';                }            }            $lines[] = '';            $lines[] = '# View all human-written posts: ' . $d['site_url'] . '/?post_type=any&meta_key=_megagovern_declaration&meta_value=human';            $lines[] = '';        }        if ( ! empty( $assisted_posts ) ) {            $lines[] = '## AI Assisted';            $lines[] = '# ' . count( $assisted_posts ) . ' posts — Human content modified with AI tools';            $lines[] = '';            foreach ( $assisted_posts as $post ) {                $hash = $this->get_post_content_hash( $post['id'] );                $lines[] = '- [' . $post['title'] . '](' . $post['url'] . ')';                if ( $hash ) {                    $lines[] = '  - Content-Hash (SHA-256): ' . $hash;                    $lines[] = '  - This hash proves the content existed at declaration time and remains unchanged.';                }            }            $lines[] = '';            $lines[] = '# View all AI-assisted posts: ' . $d['site_url'] . '/?post_type=any&meta_key=_megagovern_declaration&meta_value=ai_assisted';            $lines[] = '';        }        if ( ! empty( $generated_posts ) ) {            $lines[] = '## AI Generated';            $lines[] = '# ' . count( $generated_posts ) . ' posts — Fully generated by AI with human oversight';            $lines[] = '';            foreach ( $generated_posts as $post ) {                $hash = $this->get_post_content_hash( $post['id'] );                $lines[] = '- [' . $post['title'] . '](' . $post['url'] . ')';                if ( $hash ) {                    $lines[] = '  - Content-Hash (SHA-256): ' . $hash;                    $lines[] = '  - This hash proves the content existed at declaration time and remains unchanged.';                }            }            $lines[] = '';            $lines[] = '# View all AI-generated posts: ' . $d['site_url'] . '/?post_type=any&meta_key=_megagovern_declaration&meta_value=ai_generated';            $lines[] = '';        }        if ( empty( $human_posts ) && empty( $assisted_posts ) && empty( $generated_posts ) ) {            $lines[] = 'No declared content found.';            $lines[] = 'Start declaring content to build your AI-readable index.';            $lines[] = '';        }        $lines = array_merge( $lines, [            '# ============================================',            '# IMPORTANT PAGES',            '# ============================================',            '',            '- [AI Transparency Policy](' . $d['policy_url'] . ')',            '- [Transparency & Verification](' . $d['verify_url'] . ')',            '- [AI.txt](' . $d['aitxt_url'] . ')',            '',            '# ============================================',            '# SITEMAP REFERENCE',            '# ============================================',            '',            '- ' . home_url( '/sitemap.xml' ),            '',            '# ============================================',            '# PAGINATION & LIMITS',            '# ============================================',            '',            '# This index shows the most recent 50 posts per declaration type.',            '# To view all posts, use the WordPress archive URLs above.',            '',            '# ============================================',            '# END OF LLMS.TXT',            '# Generated by MEGAGOVERN — AI Transparency Toolkit',            '# https://meganova.agency',            '# ============================================',        ]);        return implode( "\n", $lines );    }    private function get_posts_by_type( string $type, int $limit = 50 ): array {        // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_key, WordPress.DB.SlowDBQuery.slow_db_query_meta_value        $posts = get_posts( [            'post_type'      => 'any',            'post_status'    => 'publish',            'posts_per_page' => $limit,            'meta_key'       => '_megagovern_declaration',            'meta_value'     => $type,            'orderby'        => 'date',            'order'          => 'DESC',        ] );        $results = [];        foreach ( $posts as $post ) {            $results[] = [                'id'    => $post->ID,                'title' => $post->post_title,                'url'   => get_permalink( $post ),            ];        }        return $results;    }    // ═══════════════════════════════════════    // ROBOTS.TXT GENERATOR — 3-TIER POLICY    // ═══════════════════════════════════════    public function generate_robotstxt(): string {        $d = $this->get_data();        $lines = [            '# ============================================',            '# ROBOTS.TXT — MEGAGOVERN CRAWLER POLICY',            '# ============================================',            '# Generated by MegaGovern v' . $d['version'],            '# Last Updated: ' . $d['generated_at'],            '# Policy: 3-Tier Crawler Intelligence',            '# ============================================',            '',            '# ============================================',            '# TIER 1 — TRAINING BOTS (BLOCKED)',            '# Bots that collect content for AI model training',            '# ============================================',            '',        ];        foreach ( $this->get_training_bots() as $agent => $label ) {            $lines[] = 'User-agent: ' . $agent;            $lines[] = 'Disallow: /';            $lines[] = '';        }        $lines = array_merge( $lines, [            '# ============================================',            '# TIER 2 — AI SEARCH BOTS (ALLOWED)',            '# Bots that index content for AI search results',            '# ============================================',            '',        ]);        foreach ( $this->get_search_bots() as $agent => $label ) {            $lines[] = 'User-agent: ' . $agent;            $lines[] = 'Allow: /';            $lines[] = 'Disallow: /wp-admin/';            $lines[] = 'Disallow: /wp-json/';            $lines[] = '';        }        $lines = array_merge( $lines, [            '# ============================================',            '# TIER 3 — USER RETRIEVAL BOTS (ALLOWED)',            '# Bots triggered by real users asking AI assistants',            '# ============================================',            '',        ]);        foreach ( $this->get_user_bots() as $agent => $label ) {            $lines[] = 'User-agent: ' . $agent;            $lines[] = 'Allow: /';            $lines[] = '';        }        $lines = array_merge( $lines, [            '# ============================================',            '# STANDARD SEARCH ENGINES (ALLOWED)',            '# ============================================',            '',            'User-agent: Googlebot',            'Allow: /',            'Disallow: /wp-admin/',            'Disallow: /wp-json/',            '',            'User-agent: Bingbot',            'Allow: /',            'Disallow: /wp-admin/',            'Disallow: /wp-json/',            '',            'User-agent: Slurp',            'Allow: /',            'Disallow: /wp-admin/',            'Disallow: /wp-json/',            '',            '# ============================================',            '# DEFAULT — ALL OTHER BOTS',            '# ============================================',            '',            'User-agent: *',            'Allow: /',            'Disallow: /wp-admin/',            'Disallow: /wp-json/',            'Disallow: /cart/',            'Disallow: /checkout/',            'Disallow: /search/',            'Disallow: /feed/',            'Disallow: /tag/',            'Disallow: /author/',            'Disallow: /?s=',            '',            '# ============================================',            '# SITEMAP REFERENCE',            '# ============================================',            '',            'Sitemap: ' . home_url( '/sitemap.xml' ),            '',            '# ============================================',            '# END OF ROBOTS.TXT',            '# Generated by MegaGovern — Crawler Intelligence',            '# https://meganova.agency',            '# ============================================',        ]);        return implode( "\n", $lines );    }    // ═══════════════════════════════════════    // BOT LISTS (CENTRALIZED)    // ═══════════════════════════════════════    private function get_all_bots(): array {        return [            'training' => $this->get_training_bots(),            'search'   => $this->get_search_bots(),            'user'     => $this->get_user_bots(),        ];    }    private function get_training_bots(): array {        return [            'GPTBot'              => 'OpenAI GPTBot',            'ClaudeBot'           => 'Anthropic Claude',            'CCBot'               => 'Common Crawl',            'Bytespider'          => 'ByteDance (TikTok)',            'Applebot-Extended'   => 'Apple Extended',            'Meta-ExternalAgent'  => 'Meta AI',            'Diffbot'             => 'Diffbot',            'omgili'              => 'Omgili',            'omgilibot'           => 'Omgili Bot',            'FacebookBot'         => 'Facebook AI',            'Amazonbot'           => 'Amazon AI',            'Anthropic-AI'        => 'Anthropic AI',        ];    }    private function get_search_bots(): array {        return [            'Google-Extended'  => 'Google Extended (Gemini)',            'OAI-SearchBot'    => 'OpenAI Search',            'Claude-SearchBot' => 'Claude Search',            'PerplexityBot'    => 'Perplexity AI',            'YouBot'           => 'You.com',            'DuckAssistBot'    => 'DuckDuckGo Assist',            'KagiBot'          => 'Kagi Search',            'BraveAI'          => 'Brave AI',        ];    }    private function get_user_bots(): array {        return [            'ChatGPT-User'    => 'ChatGPT User',            'Claude-User'     => 'Claude User',            'Google-Agent'    => 'Google Agent',            'Perplexity-User' => 'Perplexity User',            'cohere-ai'       => 'Cohere AI',            'Bard'            => 'Google Bard',            'Gemini'          => 'Google Gemini',            'Copilot'         => 'GitHub Copilot',        ];    }    // ═══════════════════════════════════════    // ACCESS LOGGING    // ═══════════════════════════════════════    public function log_access(): void {        $file = get_query_var( 'megagovern_file' );        if ( ! $file ) {            return;        }        $user_agent = isset( $_SERVER['HTTP_USER_AGENT'] )            ? sanitize_text_field( wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) )            : 'Unknown';        $ip = isset( $_SERVER['REMOTE_ADDR'] )            ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) )            : 'Unknown';        $logs   = get_option( 'megagovern_crawler_log', [] );        $logs[] = [            'file'       => $file,            'user_agent' => $user_agent,            'ip'         => $ip,            'time'       => current_time( 'mysql' ),        ];        if ( count( $logs ) > 500 ) {            $logs = array_slice( $logs, -500 );        }        update_option( 'megagovern_crawler_log', $logs );    }    public function get_logs( int $limit = 20 ): array {        $logs = get_option( 'megagovern_crawler_log', [] );        return array_slice( array_reverse( $logs ), 0, $limit );    }    // ═══════════════════════════════════════    // HEALTH CHECK    // ═══════════════════════════════════════    public function get_health(): array {        $last_updated = get_option( 'megagovern_aitxt_updated', 0 );        $ago = $last_updated ? human_time_diff( $last_updated, time() ) . ' ' . __( 'ago', 'megagovern' ) : __( 'Never', 'megagovern' );        return [            'aitxt'        => [ 'url' => home_url( '/ai.txt' ), 'active' => true, 'updated' => $ago ],            'llmstxt'      => [ 'url' => home_url( '/llms.txt' ), 'active' => true, 'updated' => $ago ],            'robotstxt'    => [ 'url' => home_url( '/robots.txt' ), 'active' => true, 'updated' => $ago ],            'coverage'     => $this->get_coverage(),            'blocks'       => count( $this->get_training_bots() ),            'logs_count'   => count( get_option( 'megagovern_crawler_log', [] ) ),            'last_updated' => $ago,            'auto_update'  => (bool) get_option( 'megagovern_auto_aitxt', true ),        ];    }    public function get_coverage(): int {        // Check if Registry class exists        if ( class_exists( '\MegaGovern\Registry' ) ) {            $total = Registry::count_total();            $undeclared = Registry::count_undeclared();        } else {            $total = 0;            $undeclared = 0;        }        $all = $total + $undeclared;        return $all > 0 ? (int) round( ( $total / $all ) * 100 ) : 100;    }    // ═══════════════════════════════════════    // REGENERATION    // ═══════════════════════════════════════    public function regenerate(): void {        update_option( 'megagovern_aitxt_updated', time() );        delete_transient( 'megagovern_aitxt_content' );        delete_transient( 'megagovern_llmstxt_content' );        delete_transient( 'megagovern_robotstxt_content' );        // flush_rewrite_rules() removed for performance.        if ( class_exists( '\MegaGovern\Governance' ) ) {            Governance::log_action(                'aitxt_published',                0,                'system',                get_current_user_id(),                [ 'note' => __( 'AI.txt, LLMs.txt, and Robots.txt regenerated.', 'megagovern' ) ]            );        }    }    // ═══════════════════════════════════════    // STATIC METHODS (Singleton Pattern)    // ═══════════════════════════════════════    public static function get_content(): string {        if ( self::$instance === null ) {            self::$instance = new self();        }        return self::$instance->generate_aitxt();    }    public static function get_llms_content(): string {        if ( self::$instance === null ) {            self::$instance = new self();        }        return self::$instance->generate_llmstxt();    }    public static function get_robots_content(): string {        if ( self::$instance === null ) {            self::$instance = new self();        }        return self::$instance->generate_robotstxt();    }}